from collections import deque

grafo = {
    "ana": ["luis", "sol"],
    "luis": ["ana", "marta"],
    "sol": ["ana", "diego"],
    "marta": ["luis"],
    "diego": ["sol", "elena"],
    "elena": ["diego"],
}

def camino_mas_corto(inicio, fin):
    visitados = {inicio}
    cola = deque([[inicio]])
    while cola:
        camino = cola.popleft()
        nodo = camino[-1]
        if nodo == fin:
            return camino
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append(camino + [vecino])
    return None

def n_hops(inicio, minimo, maximo):
    # equivalente a [:FRIEND*minimo..maximo]
    resultado = set()
    cola = deque([(inicio, 0)])
    visitados = {(inicio, 0)}
    while cola:
        nodo, profundidad = cola.popleft()
        if minimo <= profundidad <= maximo:
            resultado.add(nodo)
        if profundidad < maximo:
            for vecino in grafo.get(nodo, []):
                estado = (vecino, profundidad + 1)
                if estado not in visitados:
                    visitados.add(estado)
                    cola.append(estado)
    resultado.discard(inicio)
    return sorted(resultado)

camino = camino_mas_corto("ana", "elena")
print(f"Camino mas corto ana->elena: {camino} ({len(camino) - 1} saltos)")
print(f"Nodos a 2-3 saltos de ana: {n_hops('ana', 2, 3)}")
